
import type { BuyerDeliveryInputRequirementResource } from './BuyerDeliveryInputRequirementResource.js';
import type { BuyerDeliveryQuoteChoiceGroupResource } from './BuyerDeliveryQuoteChoiceGroupResource.js';
import type { DeliveryAddressResource } from './DeliveryAddressResource.js';
import type { DeliveryBuyerLocationResource } from './DeliveryBuyerLocationResource.js';

export type BuyerDeliveryQuote = { "audience": "buyer" | (string & {}); /** Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "buyer_location"?: DeliveryBuyerLocationResource; /** Buyer-safe reasons no delivery option was available. Merchant configuration details are never included. */ "buyer_reasons": Array<"address_required" | "address_incomplete" | "outside_delivery_area" | "no_pickup_location_nearby" | "unavailable_for_these_items" | "temporarily_unavailable" | (string & {})>; "choice_groups": Array<BuyerDeliveryQuoteChoiceGroupResource>; "delivery_quote_id": string; /** Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "destination_address"?: DeliveryAddressResource; /** RFC3339 timestamp. Format: date-time. */ "evaluated_at": string; "evaluation_status": "complete" | "incomplete" | "degraded" | (string & {}); /** Authoritative expiry for this quote: 24 hours when every method uses fixed, tiered, or rate_table pricing, and at most 15 minutes otherwise. A cart with tracked inventory shortens it to the 5 minutes its stock check stays valid. Read this value from every response. Format: date-time. */ "expires_at": string; /** Inputs the delivery methods need. A quote requirement, such as the destination address, is input a method needs before Flint can price it. A selection requirement is input a delivery selection needs before payment, such as a recipient field or delivery window an option requires. A method that waits on the buyer's address or store, or on an address the buyer must correct, already lists the recipient fields it requires. Those requirements name the method's choice group and have no delivery_option_ids. */ "input_requirements": Array<BuyerDeliveryInputRequirementResource>; "selection_required": boolean; "status": "active" | "consumed" | "stale" | "expired" | "revoked" | (string & {}); };
